import {orientationFor} from './orientations.mjs';
import {CATALOG,PRESETS} from './catalog.mjs';
export const tileKey=t=>`${t.x},${t.y}`;
export const sameTile=(a,b)=>!!a&&!!b&&a.x===b.x&&a.y===b.y;
export function footprint(item){const d=CATALOG[item.kind];if(!d||item.x===null||item.y===null||d.wall)return [];const {width:w,height:h}=orientationFor(item.kind,item.rotation);return Array.from({length:w*h},(_,i)=>({x:item.x+i%w,y:item.y+Math.floor(i/w)}));}
export function serviceTiles(item){if(item.x===null)return {};const profile=orientationFor(item.kind,item.rotation);return Object.fromEntries(Object.entries(profile.approaches).map(([key,[x,y]])=>[key,{x:item.x+x,y:item.y+y}]));}
export function occupied(clinic){return new Set(clinic.items.filter(i=>CATALOG[i.kind]?.blocking).flatMap(footprint).map(tileKey));}
export function inside(clinic,t){const p=PRESETS[clinic.presetId];return Number.isInteger(t.x)&&Number.isInteger(t.y)&&t.x>=0&&t.y>=0&&t.x<p.width&&t.y<p.height;}
export function findPath(clinic,from,to){if(!inside(clinic,from)||!inside(clinic,to))return null;const blocks=occupied(clinic),goal=tileKey(to);if(blocks.has(goal))return null;if(sameTile(from,to))return [];const queue=[from],visited=new Map([[tileKey(from),null]]);for(let j=0;j<queue.length;j++){const t=queue[j];for(const [dx,dy]of [[1,0],[0,1],[-1,0],[0,-1]]){const n={x:t.x+dx,y:t.y+dy},k=tileKey(n);if(!inside(clinic,n)||blocks.has(k)||visited.has(k))continue;visited.set(k,t);if(k===goal){const path=[n];let back=t;while(!sameTile(back,from)){path.unshift(back);back=visited.get(tileKey(back));}return path;}queue.push(n);}}return null;}
export function validateLayout(c){const preset=PRESETS[c.presetId];if(!preset)return {ok:false,reason:'Choose a clinic first.'};const seen=new Set(),ids=new Set(),artSlots=new Set();for(const item of c.items){const d=CATALOG[item.kind];if(!d||ids.has(item.id)||!Number.isInteger(item.rotation)||item.rotation<0||item.rotation>(d.wall?0:3))return {ok:false,reason:'Unknown or duplicate furnishing.'};ids.add(item.id);if(item.x===null&&item.y===null){if(d.core)return {ok:false,reason:'Essential stations must stay in your clinic.'};continue;}if(!Number.isInteger(item.x)||!Number.isInteger(item.y))return {ok:false,reason:'Choose a floor tile.'};if(d.wall){if(item.y!==0||item.x<0||item.x>=preset.width)return {ok:false,reason:'Wall art belongs along the back wall.'};if(artSlots.has(item.x))return {ok:false,reason:'There is already art in that wall spot.'};artSlots.add(item.x);continue;}for(const tile of footprint(item)){if(!inside(c,tile))return {ok:false,reason:'Keep the item inside your clinic.'};if(d.blocking){const key=tileKey(tile);if(seen.has(key))return {ok:false,reason:'Furniture cannot overlap.'};seen.add(key);}}}
if(seen.has(tileKey(preset.entrance)))return {ok:false,reason:'Keep the entrance clear.'};for(const kind of ['counter','exam','display'])if(c.items.filter(i=>i.kind===kind&&i.x!==null).length!==1)return {ok:false,reason:'Your clinic needs its essential stations.'};
for(const item of c.items){for(const t of Object.values(serviceTiles(item))){if(!findPath(c,preset.entrance,t))return {ok:false,reason:`Leave a clear path to ${CATALOG[item.kind].name.toLowerCase()}.`};}}
return {ok:true};}
export function waitingTiles(clinic){const p=PRESETS[clinic.presetId],blocks=occupied(clinic),service=new Set(clinic.items.flatMap(i=>Object.values(serviceTiles(i))).map(tileKey));const list=p.standing.filter(t=>!blocks.has(tileKey(t))&&!service.has(tileKey(t))&&findPath(clinic,p.entrance,t));for(let y=p.height-2;y>=1&&list.length<8;y--)for(let x=1;x<p.width-1&&list.length<8;x++){const t={x,y};if(!blocks.has(tileKey(t))&&!service.has(tileKey(t))&&!list.some(a=>sameTile(a,t))&&findPath(clinic,p.entrance,t))list.push(t);}return list;}
